#include <avr/io.h>

// Assumptions:
// 1. ATmega2560 running at 16 MHz crystal (F_CPU = 16000000UL).
// 2. LED connected to Pin PB7 with current-limiting resistor.
// 3. 200 Hz Blinking => 400 Hz Pin Toggle Rate (2.5 ms per half period).
// 4. Timer 1 in CTC Mode (WGM13:0 = 0100), Prescaler N = 64.
//    OCR1A = (16,000,000 / (64 * 400)) - 1 = 625 - 1 = 624.

int main(void) {
    // 1. Configure PB7 as digital output pin for the LED
    DDRB |= (1 << PB7);

    // 2. Reset Timer 1 Control Registers
    TCCR1A = 0x00;
    TCCR1B = 0x00;
    TCNT1  = 0x0000;

    // 3. Load Compare Match Value for 2.5 ms (400 Hz toggle)
    OCR1A = 624;

    // 4. Set CTC Mode (WGM12 = 1) and Prescaler N = 64 (CS11 = 1, CS10 = 1)
    TCCR1B |= (1 << WGM12) | (1 << CS11) | (1 << CS10);

    // 5. Polling Loop
    while (1) {
        // Wait until Output Compare Flag A (OCF1A) is set in TIFR1
        if (TIFR1 & (1 << OCF1A)) {
            // Clear OCF1A flag by writing a logical '1' to its bit location
            TIFR1 |= (1 << OCF1A);

            // Toggle LED pin (PB7)
            PORTB ^= (1 << PB7);
        }
    }

    return 0;
}

// =================================================================
// PART (a): Dual Concurrent LED Blinking Program
// =================================================================
#include <avr/io.h>
#include <avr/interrupt.h>
#define F_CPU 16000000UL
#include <util/delay.h>

// LED 1: Pin PB7 (Foreground Loop, 400 Hz Toggle = 2.5 ms delay)
// LED 2: Pin PB6 (Background Timer-1 CTC ISR, 100 Hz Blink = 200 Hz Toggle)

ISR(TIMER1_COMPA_vect) {
    // Background execution: Toggle LED 2 at 200 Hz
    PORTB ^= (1 << PB6);
}

void init_timer1_ctc(void) {
    TCCR1A = 0x00;
    TCCR1B = (1 << WGM12) | (1 << CS11) | (1 << CS10); // CTC mode, Prescaler N=64
    TCNT1  = 0;
    OCR1A  = 1249;                                    // 5.0 ms compare interval
    TIMSK1 |= (1 << OCIE1A);                          // Enable Compare Match Interrupt
}

int main(void) {
    DDRB |= (1 << PB7) | (1 << PB6); // Configure PB7 and PB6 as outputs
    init_timer1_ctc();
    sei();                           // Enable Global Interrupts (I-bit in SREG)

    while (1) {
        // Foreground task: Toggle LED 1 at 400 Hz (2.5 ms per state)
        PORTB ^= (1 << PB7);
        _delay_us(2500);
    }
    return 0;
}

// =================================================================
// PART (b): External Pulse Event Counter Program
// =================================================================
#include <avr/io.h>

int main(void) {
    // 1. Configure PORTA as output to display 8-bit pulse count
    DDRA = 0xFF;
    PORTA = 0x00;

    // 2. Configure Pin PD7 (T0 pin) as input
    DDRD &= ~(1 << PD7);
    PORTD &= ~(1 << PD7); // Disable pull-up (external pulse driving)

    // 3. Reset Timer0 count register
    TCNT0 = 0x00;

    // 4. Configure Timer0 to count rising edges on pin T0:
    //    CS02=1, CS01=1, CS00=1 selects external clock on T0 pin (rising edge)
    TCCR0A = 0x00;
    TCCR0B = (1 << CS02) | (1 << CS01) | (1 << CS00);

    while (1) {
        // Continuously output the hardware pulse count from TCNT0 to PORTA
        PORTA = TCNT0;
    }
    return 0;
}

#include <avr/io.h>

int main(void) {
    // 1. Configure PORTA as 8-bit digital output to display ADC readings
    DDRA = 0xFF;
    PORTA = 0x00;

    // 2. Configure PORTF Pin 0 (ADC0) as input with pull-up disabled
    DDRF &= ~(1 << PF0);
    PORTF &= ~(1 << PF0);

    // 3. Configure ADMUX:
    //    REFS0 = 1 (Vref = AVCC with external cap at AREF pin)
    //    ADLAR = 1 (Left Adjust Result -> 8 MSB bits available directly in ADCH)
    //    MUX4:0 = 00000 (Select Analog Channel ADC0)
    ADMUX = (1 << REFS0) | (1 << ADLAR);

    // 4. Configure ADCSRA:
    //    ADEN = 1 (Enable ADC hardware)
    //    ADPS2:0 = 111 (Prescaler = 128 -> 16 MHz / 128 = 125 kHz ADC clock)
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);

    while (1) {
        // Start Conversion by setting ADSC bit in ADCSRA
        ADCSRA |= (1 << ADSC);

        // Wait for conversion to finish (ADSC returns to 0, or poll ADIF flag)
        while (ADCSRA & (1 << ADSC));

        // Read 8-bit conversion result from ADCH and deliver to digital output PORTA
        PORTA = ADCH;
    }

    return 0;
}

// =================================================================
// PART (a): Two-Switch Configurable Logic Gate Program
// =================================================================
#include <avr/io.h>

int main(void) {
    // 1. Configure Switches on PC1, PC0 as inputs with pull-up enabled
    DDRC &= ~((1 << PC1) | (1 << PC0));
    PORTC |= (1 << PC1) | (1 << PC0);

    // 2. Configure PB0 as output for logic result Y
    DDRB |= (1 << PB0);

    // Example operand inputs (e.g. from PD0 and PD1)
    uint8_t A = 1, B = 0;
    uint8_t Y = 0;

    while (1) {
        // Read switches (mask lower 2 bits of PINC)
        uint8_t sel = PINC & 0x03;

        switch (sel) {
            case 0b00: Y = (A & B);        break; // AND
            case 0b01: Y = (A | B);        break; // OR
            case 0b10: Y = (A ^ B);        break; // XOR
            case 0b11: Y = !(A & B) & 0x01; break; // NAND
        }

        if (Y) PORTB |= (1 << PB0);
        else   PORTB &= ~(1 << PB0);
    }
    return 0;
}

// =================================================================
// PART (b): 8-Bit Data Parity Detection Program
// =================================================================
#include <avr/io.h>

int main(void) {
    // PORTA as 8-bit data input with pull-ups
    DDRA = 0x00;
    PORTA = 0xFF;

    // PORTB.7 as output driving Parity Indicator LED
    DDRB |= (1 << PB7);

    while (1) {
        uint8_t data = PINA;
        uint8_t count = 0;

        // Count number of '1' bits in the byte
        for (uint8_t i = 0; i < 8; i++) {
            if (data & (1 << i)) {
                count++;
            }
        }

        // Even parity check (number of 1s is even)
        if ((count % 2) == 0) {
            PORTB |= (1 << PB7);  // Turn ON LED for Even Parity
        } else {
            PORTB &= ~(1 << PB7); // Turn OFF LED for Odd Parity
        }
    }
    return 0;
}
